  const consultContextProgrammeId = new URLSearchParams(window.location.search).get("context");
  const [consultMessages, setConsultMessages] = useState<Array<{ role: "user" | "assistant"; content: string }>>([]);
  const [search, setSearch] = useState(""); const [region, setRegion] = useState("All"); const [field, setField] = useState("All");
  const [selected, setSelected] = useState<number[]>([]); const [activeComparisonIndex, setActiveComparisonIndex] = useState(0); const [germanyQuery, setGermanyQuery] = useState(""); const [germanyCategory, setGermanyCategory] = useState(""); const [germanyLanguage, setGermanyLanguage] = useState(""); const [month, setMonth] = useState(new Date(2027, 0, 1)); const [dragging, setDragging] = useState(false); const [activeExtractionId, setActiveExtractionId] = useState<number | null>(null);
  const didFocusProgrammeDeadline = useRef(false);
  const [reminderDraft, setReminderDraft] = useState<ReminderDraft>({ enabled: true, remindSevenDays: true, remindThreeDays: true, remindOneDay: true, preferredHourUtc: 8 });
